def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    threatening_bids = []

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) > 0:
                    threatening_bids.append(float(bid))

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, DAILY_SALARY * 0.35))

    highest_prev = max(threatening_bids) if threatening_bids else 0.0
    second_prev = 0.0
    if len(threatening_bids) >= 2:
        sorted_bids = sorted(threatening_bids, reverse=True)
        second_prev = sorted_bids[int(1)]

    likely_competitors = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None and float(bid) > 0:
            likely_competitors += 1

    supply_pressure = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)

    emergency = hp <= 2 or no_water_days >= 2
    danger = hp <= 4 or no_water_days >= 1

    if emergency:
        target = max(DAILY_SALARY * 1.55, highest_prev + 8.0)
        if supply >= 22:
            target = max(DAILY_SALARY * 1.25, highest_prev + 4.0)
        return float(min(budget, target))

    if danger:
        if highest_prev >= DAILY_SALARY * 1.8:
            target = DAILY_SALARY * 0.72 if hp > 3 else DAILY_SALARY * 1.1
        else:
            target = max(DAILY_SALARY * 0.95, highest_prev + 3.0)
            if supply >= 21:
                target = max(DAILY_SALARY * 0.82, second_prev + 2.0)
        return float(min(budget, target))

    if likely_competitors <= 1:
        target = max(DAILY_SALARY * 0.42, highest_prev + 1.5)
        if highest_prev == 0:
            target = DAILY_SALARY * 0.28
        return float(min(budget, target))

    if supply_pressure >= 0.7:
        target = DAILY_SALARY * 0.58
    elif highest_prev >= DAILY_SALARY * 1.5:
        target = DAILY_SALARY * 0.22
    else:
        target = DAILY_SALARY * 0.38

    if budget < DAILY_SALARY * 3:
        target = min(target, DAILY_SALARY * 0.3)

    return float(min(budget, max(0.0, target)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append((oid, o))

    if not alive:
        return float(min(my_status.get('budget', 0.0), DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace only (immediate reaction)
    prev_bids = []
    prev_hp_after = []
    for oid, o in alive:
        prev = o.get('previous_trace', {}) or {}
        if prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid', 0.0)))
            except Exception:
                pass
        if prev.get('hp_after') is not None:
            try:
                prev_hp_after.append(float(prev.get('hp_after', 0.0)))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_highest_prev_bid = 0.0
    if len(prev_bids) >= 2:
        sorted_b = sorted(prev_bids, reverse=True)
        second_highest_prev_bid = sorted_b[1]

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))

    # Estimate how many allocations are possible this day (not exact, but guides aggressiveness)
    # Each unit of water is assumed to reduce no_water_days; we buy enough to cover WATER_REQ needs.
    # Use supply bands to decide whether to contest.
    supply_band = 'low'
    if supply >= 20.0:
        supply_band = 'high'
    elif supply >= 17.0:
        supply_band = 'mid'

    # If someone previously bid extremely high, they likely are contesting hard.
    # Avoid matching unless my HP is low.
    critical = my_hp <= 2.5
    very_low = my_hp <= 1.0

    # Target bid: beat the median/second-highest but stay below the highest unless critical.
    # Also incorporate supply band: with higher supply, lower pressure.
    base = 0.0
    if supply_band == 'high':
        base = max(DAILY_SALARY * 0.35, second_highest_prev_bid * 0.95)
    elif supply_band == 'mid':
        base = max(DAILY_SALARY * 0.45, second_highest_prev_bid * 1.02)
    else:
        base = max(DAILY_SALARY * 0.55, second_highest_prev_bid * 1.05)

    # If the highest yesterday was far above typical, don't overreact unless critical.
    if highest_prev_bid >= DAILY_SALARY * 1.65:  # ~149
        if very_low:
            bid = max(base, DAILY_SALARY * 0.95)
        elif critical:
            bid = max(base, DAILY_SALARY * 0.75)
        else:
            # stay competitive but not top-end
            bid = min(base, DAILY_SALARY * 0.65)
    else:
        # No extreme contest detected; bid to secure against low bidders.
        if critical:
            bid = max(base, DAILY_SALARY * 0.8)
        else:
            bid = max(base, DAILY_SALARY * 0.55)

    # Hard caps to avoid bankruptcy
    # Keep some budget for future days; scale with remaining budget and no_water_days.
    no_water_days = float(my_status.get('no_water_days', 0.0))
    budget_safety = 0.25 if no_water_days <= 1.0 else 0.15
    max_affordable = my_budget * (1.0 - budget_safety)
    if max_affordable < 0.0:
        max_affordable = 0.0

    # Final bid bounded by budget and a reasonable contest ceiling
    ceiling = DAILY_SALARY * 0.95 if critical else DAILY_SALARY * 0.7
    bid = float(min(max_affordable, bid, ceiling))

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # 1. If no active opponents, bid minimally to save budget.
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    # 2. Critical HP / No water for days: Prioritize survival. Bid aggressively.
    if my_status['hp'] <= 2 or my_status['no_water_days'] > 0:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    # 3. Collect yesterday's bids from active opponents' previous_trace
    yesterday_bids = []
    for opp in alive_opponents:
        prev_trace = opp.get('previous_trace')
        if prev_trace and prev_trace.get('bid') is not None:
            yesterday_bids.append(prev_trace['bid'])

    # Base bid if no relevant yesterday bids or as a fallback
    base_bid = DAILY_SALARY * 0.55 # A moderate default bid

    # 4. Decision logic based on yesterday's highest pressure and my status
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        # Threshold for high bids (from example strategy)
        high_bid_threshold = DAILY_SALARY * 0.85

        if highest_prev_bid >= high_bid_threshold:
            # Opponents are bidding very high
            if my_status['hp'] > 3: # My HP is good, can afford to be less aggressive
                # Conserve budget, but still aim to be competitive (e.g., 60% of salary)
                return min(my_status['budget'], DAILY_SALARY * 0.6)
            else: # My HP is moderate/low, need to secure water aggressively
                return min(my_status['budget'], DAILY_SALARY * 0.95)
        else:
            # Opponents' highest bid was moderate or low
            # Bid slightly above it to secure water, ensuring it's at least the base bid.
            return min(my_status['budget'], max(base_bid, highest_prev_bid + 1.5))

    # Fallback if no yesterday bids (e.g., Day 1, or all opponents bid 0)
    return min(my_status['budget'], base_bid)

